<script>
  (function() {
    // Interactive Quick Filter Pill Switching
    const quickPills = document.querySelectorAll('#quickPillsGroup .filter-pill');
    quickPills.forEach(pill => {
      pill.addEventListener('click', () => {
        quickPills.forEach(p => {
          p.classList.remove('bg-primary', 'text-on-primary');
          p.classList.add('bg-surface-container-high', 'text-on-surface');
        });
        pill.classList.remove('bg-surface-container-high', 'text-on-surface');
        pill.classList.add('bg-primary', 'text-on-primary');
      });
    });

    // Toggle Filter Drawer Accordion
    const filterBtn = document.getElementById('openFilterBtn');
    const filterDrawer = document.getElementById('filterDrawer');
    if (filterBtn && filterDrawer) {
      filterBtn.addEventListener('click', () => {
        filterDrawer.classList.toggle('hidden');
      });
    }

    // Interactive Size Selector Pills
    const sizePills = document.querySelectorAll('.size-pill');
    sizePills.forEach(sp => {
      sp.addEventListener('click', () => {
        sizePills.forEach(s => {
          s.classList.remove('bg-primary', 'text-on-primary');
          s.classList.add('bg-surface-container-lowest', 'text-on-surface');
        });
        sp.classList.remove('bg-surface-container-lowest', 'text-on-surface');
        sp.classList.add('bg-primary', 'text-on-primary');
      });
    });

    // Interactive Availability Mode Toggles
    const modeBtns = document.querySelectorAll('.filter-mode-btn');
    modeBtns.forEach(mb => {
      mb.addEventListener('click', () => {
        modeBtns.forEach(b => {
          b.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
          b.classList.add('text-on-surface-variant');
        });
        mb.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
        mb.classList.remove('text-on-surface-variant');
      });
    });

    // Wishlist Toggle Animation
    const wishButtons = document.querySelectorAll('button:has(.material-symbols-outlined:contains("favorite"))');
    document.querySelectorAll('.material-symbols-outlined').forEach(icon => {
      if (icon.textContent.trim() === 'favorite') {
        const parentBtn = icon.closest('button');
        if (parentBtn) {
          parentBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const isFilled = icon.getAttribute('style') && icon.getAttribute('style').includes('FILL');
            if (isFilled) {
              icon.removeAttribute('style');
              parentBtn.classList.remove('text-error');
            } else {
              icon.setAttribute('style', "font-variation-settings: 'FILL' 1;");
              parentBtn.classList.add('text-error');
            }
          });
        }
      }
    });
  })();
